TAB_ACTIONS_PARAMETERS_22 = "Meta-Actions"
TAB_ACTIONS_PARAMETERS_23 = "Include the contents of the specified form:|r<BR/> includeForm=&lt;form name&gt;<BR/>"
TAB_ACTIONS_PARAMETERS_24 = "Note:|r This does not accept criteria. It must appear on a line by itself. You cannot include a form in itself, nor should you include a form which includes another form which includes the first (e.g. form A includes form B includes form A == BAD)."
TAB_ACTIONS_PARAMETERS_25 = "Call the specified form:|r<BR/> callForm=&lt;form name&gt;<BR/>"
TAB_ACTIONS_PARAMETERS_26 = "This will try to find a usable action in the specified form, if the criteria on the callForm action are satisfied."

TAB_LIST_CRITERIA = "List of recognised criteria"
TAB_CRITERIA_1 = "<BR/>Append zero or more criteria to an action.  All criteria must be true for that action to be used.  List your actions one after another on separate lines.  The first action that matches all criteria is used."
TAB_CRITERIA_2 = "<BR/>Multiple values within curly braces ({}) means choose one or more.  If more than one is chosen, separate them with commas (e.g. ifRace=Human,Gnome) and the criteria will match if any of the choices match.  If a multiple-choice criteria is negated with a \"Not\" (e.g. ifNotRace=Human,Gnome) then the criteria will match only if none of the choices match.  Square brackets ([]) mean the value is optional.  Do NOT leave the curly braces or square brackets in your form."
TAB_CRITERIA_ACTION = "Action Criteria:"
